const items = $input.all();
if (items.length === 0) {
  throw new Error("No se encontraron artículos publicados. Verifica WP_URL y WP_AUTH_BASIC en Settings → Variables.");
}
return items.map(item => ({
  json: {
    id: item.json.id,
    title: item.json.title?.rendered || "",
    modified: item.json.modified,
    link: item.json.link,
    slug: item.json.slug
  }
}));

const post = $input.first().json;
const raw = post.content?.raw || '';
const meta = post.meta || {};
const title = post.title?.raw || post.title?.rendered || '';
const postId = post.id;
const postUrl = post.link || '';

// ── Detectar builder ──────────────────────────────────────────
let builderType = 'classic';
if (raw.includes('[et_pb_')) {
  builderType = 'divi';
} else if (raw.includes('<!-- wp:')) {
  builderType = 'gutenberg';
} else if (meta._elementor_data && meta._elementor_data.length > 10) {
  builderType = 'elementor';
} else if (raw.includes('elementor-section') || raw.includes('data-elementor-type')) {
  builderType = 'elementor_html';
}

let textChunks = [], imageMap = {}, structuredData = {};

// ── Divi ──────────────────────────────────────────────────────
if (builderType === 'divi') {
  const re = /(\[et_pb_text[^\]]*\])([\s\S]*?)(\[\/et_pb_text\])/g;
  let m, idx = 0;
  while ((m = re.exec(raw)) !== null) {
    const text = m[2].trim();
    if (text.length > 20) {
      textChunks.push({ id: 'chunk_' + idx, text, openTag: m[1], closeTag: m[3] });
      idx++;
    }
  }
  structuredData = { originalContent: raw };

// ── Gutenberg ─────────────────────────────────────────────────
} else if (builderType === 'gutenberg') {
  const re = /(<!-- wp:(paragraph|heading)(\s[^>]*)? -->\n?)([\s\S]*?)(<!-- \/wp:\2 -->)/g;
  let m, idx = 0;
  while ((m = re.exec(raw)) !== null) {
    const text = m[4].trim();
    if (text.length > 20) {
      textChunks.push({ id: 'chunk_' + idx, blockType: m[2], openComment: m[1], text, closeComment: m[5] });
      idx++;
    }
  }
  structuredData = { originalContent: raw };

// ── Elementor (JSON meta) ─────────────────────────────────────
} else if (builderType === 'elementor') {
  let elData = [];
  try { elData = JSON.parse(meta._elementor_data); } catch(e) {}
  function traverse(els) {
    if (!Array.isArray(els)) return;
    els.forEach(el => {
      if (el.elType === 'widget' && ['text-editor', 'heading', 'button'].includes(el.widgetType)) {
        const text = el.settings?.editor || el.settings?.title || el.settings?.text || '';
        if (text && text.length > 20) {
          textChunks.push({ id: el.id, widgetType: el.widgetType, text });
        }
      }
      if (el.elements?.length) traverse(el.elements);
    });
  }
  traverse(elData);
  structuredData = { elementorDataStr: JSON.stringify(elData) };

// ── Classic / Elementor HTML ──────────────────────────────────
} else {
  let processed = raw;
  const imgRe = /(<figure[^>]*>[\s\S]*?<\/figure>|<img[^>]+\/?>)/gi;
  let m, imgIdx = 0;
  // Reset regex before using exec
  let imgMatch;
  const imgRe2 = /(<figure[^>]*>[\s\S]*?<\/figure>|<img[^>]+\/?>)/gi;
  while ((imgMatch = imgRe2.exec(raw)) !== null) {
    const ph = 'IMGPH' + imgIdx + 'ENDPH';
    imageMap[ph] = imgMatch[1];
    processed = processed.replace(imgMatch[1], ph);
    imgIdx++;
  }
  textChunks.push({ id: 'chunk_0', text: processed });
  structuredData = {};
}

// ── Preparar prompts para Groq ────────────────────────────────
const systemPrompt = `Eres un experto en SEO semántico y AEO (Answer Engine Optimization) para WordPress.
Tu tarea: reescribir fragmentos de contenido para mantenerlos frescos y optimizados.

REGLAS ABSOLUTAS:
1. Mantén EXACTAMENTE el mismo tema e ideas del original. NO inventes información nueva.
2. NO cambies el idioma del contenido.
3. PRESERVA todos los tags HTML exactamente (clases, atributos, estructura interna).
4. Los placeholders IMGPH0ENDPH, IMGPH1ENDPH... deben quedar EXACTOS en su posición original.
5. Mejora semántica SEO: usa sinónimos, entidades relacionadas, términos long-tail naturales.
6. Optimiza para AEO: respuestas directas al inicio de párrafos, listas bien estructuradas, preguntas frecuentes naturales.
7. Responde ÚNICAMENTE con JSON válido, sin texto adicional.`;

const jsonFormatExample = '{"chunks": [{"id": "chunk_0", "text": "contenido reescrito aquí"}]}';
const chunksForPrompt = JSON.stringify(textChunks.map(c => ({ id: c.id, text: c.text })), null, 2);

const userPrompt = 'Artículo: "' + title + '"\nBuilder detectado: ' + builderType + '\n\nDevuelve SOLO este JSON (sin texto extra):\n' + jsonFormatExample + '\n\nFragmentos a reescribir:\n' + chunksForPrompt;

return [{
  json: {
    postId,
    postTitle: title,
    postUrl,
    builderType,
    textChunks,
    structuredData,
    imageMap,
    originalRaw: raw,
    originalMeta: meta,
    groqSystemPrompt: systemPrompt,
    groqUserPrompt: userPrompt,
    topicForTrends: title
  }
}];

// Recibimos N items del RSS (uno por noticia) + posible item de error si RSS falló
const allItems = $input.all();
const extraction = $('🔍 Extraer Contenido').first().json;

// Filtrar items válidos de Google News (tienen campo title)
let newsContext = '';
try {
  const newsItems = allItems.filter(i => i.json && i.json.title && !i.json.error);
  if (newsItems.length > 0) {
    const headlines = newsItems
      .slice(0, 5)
      .map(i => '- ' + i.json.title + (i.json.contentSnippet ? ': ' + i.json.contentSnippet.slice(0, 120) : ''))
      .join('\n');
    newsContext = '\n\nNoticias actuales sobre este tema (referencia de tendencias SEO):\n' + headlines;
  }
} catch(e) {
  newsContext = '';
}

const enrichedUserPrompt = extraction.groqUserPrompt + newsContext;
return [{ json: { ...extraction, enrichedUserPrompt, retryCount: 0 } }];

const data = $input.first().json;
const extraction = $('🔍 Extraer Contenido').first().json;
const { builderType, originalRaw, textChunks } = extraction;
const updateBody = data.updateBody || {};
const errors = [];

// ── 1. Groq devolvió chunks ────────────────────────────────────
if (data.chunksRewritten === 0) {
  errors.push('Groq no devolvió ningún fragmento reescrito');
}

// ── 2. Obtener el contenido nuevo para validar ─────────────────
const newContent = updateBody.content || 
  (updateBody.meta?._elementor_data) || '';

if (!newContent || newContent.length < 50) {
  errors.push('Contenido nuevo vacío o demasiado corto');
}

// ── 3. No debe ser más corto que 40% del original ──────────────
if (newContent && originalRaw) {
  const ratio = newContent.length / originalRaw.length;
  if (ratio < 0.4) {
    errors.push(`Contenido nuevo sospechosamente corto (${Math.round(ratio*100)}% del original)`);
  }
}

// ── 4. Placeholders de imagen no deben quedar sin reemplazar ───
if (newContent && newContent.includes('ENDPH')) {
  errors.push('Quedan placeholders de imágenes sin reemplazar (IMGPH...ENDPH)');
}

// ── 5. Estructura del builder debe estar intacta ───────────────
if (builderType === 'divi' && newContent && !newContent.includes('[et_pb_')) {
  errors.push('Divi: shortcodes [et_pb_] desaparecieron del contenido');
}
if (builderType === 'gutenberg' && newContent && !newContent.includes('<!-- wp:')) {
  errors.push('Gutenberg: bloques <!-- wp: --> desaparecieron del contenido');
}
if (builderType === 'elementor') {
  try { JSON.parse(newContent); } catch(e) {
    errors.push('Elementor: _elementor_data no es JSON válido');
  }
}

const esValido = errors.length === 0;

return [{
  json: {
    ...data,
    esValido,
    erroresValidacion: errors,
    resumenValidacion: esValido
      ? '✅ Contenido validado — seguro actualizar'
      : '❌ BLOQUEADO: ' + errors.join(' | ')
  }
}];

const data = $input.first().json;
console.error('=== ACTUALIZACIÓN BLOQUEADA ===');
console.error('Post ID:', data.postId);
console.error('Título:', data.postTitle);
console.error('Builder:', data.builderType);
console.error('Errores:', data.erroresValidacion.join(' | '));
console.error('El artículo NO fue modificado. Revisar logs para diagnóstico.');

// Devolver info para que quede visible en la ejecución
return [{
  json: {
    estado: 'BLOQUEADO_SIN_ACTUALIZAR',
    postId: data.postId,
    postTitle: data.postTitle,
    motivo: data.erroresValidacion,
    accion: 'Artículo preservado intacto. Revisar logs de ejecución.'
  }
}];

const item = $input.first().json;
const retryCount = (item.retryCount || 0) + 1;
const lastError = item.error || 'Error desconocido en Groq API';
console.warn(`Groq falló. Intento ${retryCount}/3. Error: ${lastError}`);
return [{ json: { ...item, retryCount, lastError } }];

