const groqRaw = $input.first().json;
const extraction = $('🔍 Extraer Contenido').first().json;

// ── Parsear JSON de respuesta ─────────────────────────────────
const responseText = groqRaw.choices?.[0]?.message?.content || '{}';
let rewrittenData;
try {
  rewrittenData = typeof responseText === 'object' ? responseText : JSON.parse(responseText);
} catch(e) {
  const match = String(responseText).match(/\{[\s\S]*\}/);
  try { rewrittenData = match ? JSON.parse(match[0]) : { chunks: [] }; }
  catch(e2) { rewrittenData = { chunks: [] }; }
}

const chunksMap = {};
(rewrittenData.chunks || []).forEach(c => { if (c.id && c.text) chunksMap[c.id] = c.text; });
const chunksRewritten = Object.keys(chunksMap).length;

if (chunksRewritten === 0) {
  console.warn('⚠️ Grok no devolvió chunks. Raw:', String(responseText).slice(0, 300));
}

return [{
  json: {
    ...extraction,
    chunksMap,
    chunksRewritten,
    groqRawResponse: String(responseText).slice(0, 200)
  }
}];

const data = $input.first().json;
const { textChunks, chunksMap, originalRaw, postId, postTitle, chunksRewritten } = data;

// Reemplazar cada [et_pb_text]...[/et_pb_text] con el chunk reescrito
let idx = 0;
const newContent = originalRaw.replace(
  /(\[et_pb_text[^\]]*\])([\s\S]*?)(\[\/et_pb_text\])/g,
  (match, openTag, oldText, closeTag) => {
    const chunk = textChunks[idx];
    idx++;
    if (!chunk) return match;
    const newText = chunksMap[chunk.id];
    if (!newText) {
      console.warn('Divi chunk sin reescribir:', chunk.id, '— preservando original');
      return match;
    }
    return openTag + '\n' + newText + '\n' + closeTag;
  }
);

// Verificación: shortcodes Divi deben seguir presentes
if (!newContent.includes('[et_pb_')) {
  throw new Error('Divi: los shortcodes [et_pb_] desaparecieron tras la reconstrucción');
}

return [{ json: {
  postId, postTitle,
  builderType: 'divi',
  chunksRewritten,
  updateBody: { content: newContent }
}}];

const data = $input.first().json;
const { textChunks, chunksMap, originalRaw, postId, postTitle, chunksRewritten } = data;

let idx = 0;
const newContent = originalRaw.replace(
  /(<!-- wp:(paragraph|heading)(\s[^>]*)? -->\n?)([\s\S]*?)(<!-- \/wp:\2 -->)/g,
  (match, openComment, blockType, attrs, oldContent, closeComment) => {
    const chunk = textChunks[idx];
    idx++;
    if (!chunk) return match;
    const newText = chunksMap[chunk.id];
    if (!newText) {
      console.warn('Gutenberg chunk sin reescribir:', chunk.id, '— preservando original');
      return match;
    }
    return openComment + newText + '\n' + closeComment;
  }
);

// Verificación: bloques Gutenberg deben seguir presentes
if (!newContent.includes('<!-- wp:')) {
  throw new Error('Gutenberg: los bloques <!-- wp: --> desaparecieron tras la reconstrucción');
}

return [{ json: {
  postId, postTitle,
  builderType: 'gutenberg',
  chunksRewritten,
  updateBody: { content: newContent }
}}];

const data = $input.first().json;
const { structuredData, chunksMap, postId, postTitle, chunksRewritten } = data;

let elData = [];
try {
  elData = JSON.parse(structuredData.elementorDataStr || '[]');
} catch(e) {
  throw new Error('Elementor: no se pudo parsear _elementor_data: ' + e.message);
}

// Recorrer árbol Elementor y actualizar widgets
function updateEl(elements) {
  if (!Array.isArray(elements)) return elements;
  return elements.map(el => {
    if (el.elType === 'widget' && chunksMap[el.id]) {
      const newText = chunksMap[el.id];
      el = { ...el, settings: { ...el.settings } };
      if (el.widgetType === 'text-editor') el.settings.editor = newText;
      else if (el.widgetType === 'heading')     el.settings.title  = newText;
      else if (el.widgetType === 'button')      el.settings.text   = newText;
    }
    if (el.elements?.length) el.elements = updateEl(el.elements);
    return el;
  });
}

const updatedData = updateEl(elData);
const newElementorJson = JSON.stringify(updatedData);

// Verificación: debe ser JSON válido
try { JSON.parse(newElementorJson); } catch(e) {
  throw new Error('Elementor: _elementor_data no es JSON válido tras reconstrucción');
}

return [{ json: {
  postId, postTitle,
  builderType: 'elementor',
  chunksRewritten,
  updateBody: { meta: { _elementor_data: newElementorJson } }
}}];

const data = $input.first().json;
const { chunksMap, imageMap, originalRaw, postId, postTitle, chunksRewritten, builderType } = data;

// El contenido es HTML plano (Classic Editor o Elementor HTML)
let reconstructed = chunksMap['chunk_0'] || originalRaw;

// Restaurar imágenes reemplazadas por placeholders
const imgMapData = imageMap || {};
const placeholders = Object.keys(imgMapData);
if (placeholders.length > 0) {
  placeholders.forEach(placeholder => {
    reconstructed = reconstructed.split(placeholder).join(imgMapData[placeholder]);
  });
  // Verificar que no quedan placeholders sin reemplazar
  if (reconstructed.includes('ENDPH')) {
    throw new Error('Classic: quedan placeholders de imágenes sin reemplazar');
  }
}

return [{ json: {
  postId, postTitle,
  builderType: builderType || 'classic',
  chunksRewritten,
  updateBody: { content: reconstructed }
}}];

const wpResponse = $input.first().json;
const parsedGroq = $('📦 Parsear Respuesta Groq').first().json;

const postId    = parsedGroq.postId;
const postTitle = parsedGroq.postTitle;
const postUrl   = parsedGroq.postUrl;
const builderType = parsedGroq.builderType;
const textChunks  = parsedGroq.textChunks || [];
const chunksMap   = parsedGroq.chunksMap  || {};
const modifiedDate = wpResponse.modified || new Date().toISOString();

const stripHtml = html =>
  String(html || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();

let comparisonRows = '';
let changesCount = 0;

textChunks.forEach(chunk => {
  const original  = stripHtml(chunk.text || '').slice(0, 500);
  const rewritten = stripHtml(chunksMap[chunk.id] || chunk.text || '').slice(0, 500);
  if (original === rewritten) return;
  changesCount++;
  comparisonRows += `
    <tr>
      <td style="padding:12px;border:1px solid #ddd;background:#fff5f5;vertical-align:top;width:50%;font-size:14px;color:#333">
        <span style="display:block;font-size:11px;color:#999;margin-bottom:6px;text-transform:uppercase;letter-spacing:1px">Antes</span>
        ${original}
      </td>
      <td style="padding:12px;border:1px solid #ddd;background:#f5fff5;vertical-align:top;width:50%;font-size:14px;color:#333">
        <span style="display:block;font-size:11px;color:#999;margin-bottom:6px;text-transform:uppercase;letter-spacing:1px">Después</span>
        ${rewritten}
      </td>
    </tr>`;
});

if (!comparisonRows) {
  comparisonRows = `<tr><td colspan="2" style="padding:16px;text-align:center;color:#888;font-style:italic">
    Cambios aplicados en estructura HTML/shortcodes (sin diferencias de texto plano detectables)
  </td></tr>`;
}

const htmlBody = `
<div style="font-family:Arial,sans-serif;max-width:820px;margin:0 auto;color:#333">
  <div style="background:#0a63c9;padding:20px 24px;border-radius:6px 6px 0 0">
    <h2 style="margin:0;color:#fff;font-size:20px">✅ Artículo actualizado · Reporte automático</h2>
  </div>
  <div style="border:1px solid #ddd;border-top:none;border-radius:0 0 6px 6px;padding:24px">
    <table style="width:100%;border-collapse:collapse;margin-bottom:24px;font-size:14px">
      <tr style="border-bottom:1px solid #eee">
        <td style="padding:10px 8px;font-weight:bold;color:#555;width:130px">Post ID</td>
        <td style="padding:10px 8px"><code style="background:#f4f4f4;padding:2px 6px;border-radius:3px">${postId}</code></td>
      </tr>
      <tr style="background:#fafafa;border-bottom:1px solid #eee">
        <td style="padding:10px 8px;font-weight:bold;color:#555">Título</td>
        <td style="padding:10px 8px">${postTitle}</td>
      </tr>
      <tr style="border-bottom:1px solid #eee">
        <td style="padding:10px 8px;font-weight:bold;color:#555">Builder</td>
        <td style="padding:10px 8px"><span style="background:#e8f0fe;color:#1a73e8;padding:2px 8px;border-radius:12px;font-size:12px">${builderType}</span></td>
      </tr>
      <tr style="background:#fafafa;border-bottom:1px solid #eee">
        <td style="padding:10px 8px;font-weight:bold;color:#555">Modificado</td>
        <td style="padding:10px 8px">${new Date(modifiedDate).toLocaleString('es-ES', {timeZone:'Europe/Madrid'})}</td>
      </tr>
      <tr style="border-bottom:1px solid #eee">
        <td style="padding:10px 8px;font-weight:bold;color:#555">Bloques cambiados</td>
        <td style="padding:10px 8px"><strong style="color:#0a63c9">${changesCount}</strong> de ${textChunks.length}</td>
      </tr>
      <tr style="background:#fafafa">
        <td style="padding:10px 8px;font-weight:bold;color:#555">Ver artículo</td>
        <td style="padding:10px 8px"><a href="${postUrl}" style="color:#0a63c9;font-weight:bold">${postUrl}</a></td>
      </tr>
    </table>

    <h3 style="color:#333;margin:0 0 12px;font-size:16px">Comparativa de cambios</h3>
    <table style="width:100%;border-collapse:collapse;font-size:13px">
      ${comparisonRows}
    </table>

    <p style="color:#aaa;font-size:11px;margin-top:24px;border-top:1px solid #eee;padding-top:12px">
      Automatización RRSS · WordPress Content Renewal
    </p>
  </div>
</div>`;

return [{
  json: {
    postId,
    postTitle,
    postUrl,
    builderType,
    changesCount,
    emailHtml: htmlBody,
    subject: `✅ Actualizado: ${postTitle} (ID ${postId}) · ${changesCount} bloques modificados`
  }
}];
